func (r *ResourceF5XCInfraprotectAsn) Delete(ctx context.Context, request resource.DeleteRequest, response *resource.DeleteResponse) {
	var data ResourceF5XCInfraprotectAsnModel

	// Read Terraform prior state data into the model
	response.Diagnostics.Append(request.State.Get(ctx, &data)...)
	if response.Diagnostics.HasError() {
		return
	}

	duration, err := time.ParseDuration("10m0s")
	if err != nil {
		response.Diagnostics.AddError(
			"Invalid Duration Format",
			fmt.Sprintf("Could not parse 'timeout' value %q: %s. "+
				"Please use a valid Go duration string like '10m', '1h30m' or '30s'.",
				"10m0s", err.Error()),
		)
		return
	}

	deleteTimeout, diags := data.Timeouts.Delete(ctx, duration)
	response.Diagnostics.Append(diags...)
	if response.Diagnostics.HasError() {
		return
	}

	ctx, cancel := context.WithTimeout(ctx, deleteTimeout)
	defer cancel()

	// Standard Delete Logic
	opts := []vesapi.CallOpt{}
	opts = append(opts, vesapi.WithFailIfReferred())

	err = r.client.DeleteObject(ctx, ves_io_schema_infraprotect_asn.ObjectType, data.Namespace.ValueString(), data.Name.ValueString(), opts...)

	if err != nil {
		if strings.Contains(err.Error(), "status code 404") || strings.Contains(err.Error(), "NotFound") {
			// Object already gone, Terraform take it easy
			return
		}

		response.Diagnostics.AddError(
			"Client Error", utils.SanitizeAPIError(ctx, "delete", "infraprotect_asn", err),
		)
		return
	}

}
func (r *ResourceF5XCInfraprotectAsn) ImportState(ctx context.Context, req resource.ImportStateRequest, response *resource.ImportStateResponse) {
	// Import ID format: namespace/name
	parts := strings.Split(req.ID, "/")
	if len(parts) != 2 {
		response.Diagnostics.AddError(
			"Invalid Import ID",
			fmt.Sprintf("Expected import ID format: namespace/name, got: %s", req.ID),
		)
		return
	}
	if parts[0] == "" {
		response.Diagnostics.AddError(
			"Invalid Import ID",
			fmt.Sprintf("Expected import ID format: namespace/name, got: %s (namespace is empty)", req.ID),
		)
		return
	}
	response.Diagnostics.Append(response.State.SetAttribute(ctx, path.Root("namespace"), parts[0])...)
	if parts[1] == "" {
		response.Diagnostics.AddError(
			"Invalid Import ID",
			fmt.Sprintf("Expected import ID format: namespace/name, got: %s (name is empty)", req.ID),
		)
		return
	}
	response.Diagnostics.Append(response.State.SetAttribute(ctx, path.Root("name"), parts[1])...)
}
